/**
 * 负责有序死亡波、角色死亡钩子、枪击选择、遗言与警徽交接。输入是待处理的死亡名单、
 * 原死因与原生命行动权限；输出是按原顺序提交的死亡、事件和内部关联凭证。实际生命修改和唯一已结算
 * 账本委托 DeathCommitter，双生、动物、婚约及狼美人关系事实归具体贡献；已提交整波在梦／遗言前交角色扩展，
 * 野孩子贡献自行核对榜样原生命。参数仍使用同一深只读规则视图，不建立第二份角色状态。
 * 枪的资格捕获与复验归共同 owner，请求、等待、目标原生命及许可开关仍在本结算器。
 * 本模块不切换阶段或确定最终胜负；关系扩展、遗言、警徽和枪的最终过期保留原执行顺序。
 */
import { refreshWolfKnifeInheritanceAtCheckpoint } from "../../rulesets/wolf-knife-inheritance-plan";
import { AnimalDeathWavePreparation } from "../mechanisms/roles/animal_dream/ports";
import {
  planDeathWave,
  openDeathWave,
  deathExecutionContext,
  type DeathExecutionContext,
  deathWaveOriginalLives,
  deathWavePoisonMetadata,
  type DeathWaveUnit,
  preflightDeathWaveData,
  DeathCommitReceipt,
  type DeathOriginalLife,
} from "./death-wave";
import type { NightPoisonRoute } from "../../core/domain/night_effects";
import { DeathCommitter } from "./death-committer";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
import {
  FragrantDeathWavePublication,
  isFragrantPairBoard,
  prepareFragrantDeathWave,
  commitFragrantDeathWave,
  publishFragrantDeathWave,
  cancelFragrantDeathWave,
  fragrantAuthoritySnapshot,
} from "../mechanisms/roles/fragrant_pair_seer/ports";
import { assertMagicianRosterCurrent } from "../mechanisms/roles/magician/night_frame";
import {
  isMagicianBoard,
  resolveMagicianNightTarget,
} from "../mechanisms/roles/magician/night_frame";
import { nightmareFearBlocks } from "../mechanisms/roles/nightmare_shadow/night_frame";
import { demonHunterNativeGunCurrent } from "../mechanisms/roles/demon_hunter/ports";
import { WeddingDeathWavePublication } from "../mechanisms/roles/ghost_bride/ports";
import { expandLoversWave } from "../mechanisms/roles/cupid/relation";
import type { BoardConfig, LastWordsPolicy } from "../../core/domain/board";
import { captureNightLife, livingNightLife } from "../../core/domain/night_effects";
import { COMPONENT } from "../../core/domain/components/names";
import {
  ActionProvider,
  EntityId,
  GameEvent,
  Phase,
  Role,
  RuntimeSnapshot,
  DeathCause,
  type DeathSources,
  type DeathShotSelection,
} from "../../core/domain/model";
import type { RoleComponent } from "../../core/domain/components/role";
import { World } from "../../core/domain/world";
import { ToolGateway } from "../gateway/tool_gateway";
import { getDefaultLastWordsMechanism } from "../mechanisms/last_words/last_words_mechanism";
import type { LastWordsGrantContext } from "../mechanisms/last_words/last_words_mechanism";
import { resolveSheriffBadge } from "../mechanisms/sheriff/badge_choice";
import { GameActionRequestFactory } from "./action_request_factory";
import { EventRegistry } from "./event_registry";
import type { DreamNightEffects } from "../../core/domain/dream-night-effects";
import {
  captureDeathShotEligibility,
  firstDeathGuns,
  finishDeathGuns,
} from "../mechanisms/roles/death_abilities";

/** 一次角色死亡动作的窗口；所有 permit 在退出该回调时关闭，不跨波复用。 */
interface DeathWaveActions {
  phase: Phase;
  day: number;
  permits: Array<ReturnType<World["openDeathAction"]>>;
  isCurrent: () => boolean;
}

/** 连续结算死亡波，动作阶段仍由 PhaseManager 推进。 */
export class DeathResolution {
  // 只捕获原结算器；每条关系边在原表达式处晚读 World、事件、日期及阶段。
  private readonly weddingDeathWave = (() => {
    const resolution = this;
    return new WeddingDeathWavePublication({
      get world() {
        return resolution.world;
      },
      get events() {
        return resolution.events;
      },
      get day() {
        return resolution.state.day;
      },
      get phase() {
        return resolution.state.phase;
      },
    });
  })();
  private readonly lastWordsMechanism = getDefaultLastWordsMechanism();
  // 只捕获结算器本身；每次 World、事件和运行状态读取仍发生在原命令表达式处。
  private readonly deathCommitter = (() => {
    const resolution = this;
    return new DeathCommitter({
      get world() {
        return resolution.world;
      },
      get events() {
        return resolution.events;
      },
      get state() {
        return resolution.state;
      },
    });
  })();
  // 只捕获原结算器；每次窄查询/读取/发布仍在原表达式处使用当前 World 与状态。
  private readonly fragrantDeathWave = (() => {
    const resolution = this;
    return new FragrantDeathWavePublication({
      actorId: () => resolution.world.getEntityIdsByRole(Role.FragrantPhantom)[0]!,
      get phase() {
        return resolution.state.phase;
      },
      get day() {
        return resolution.state.day;
      },
      get events() {
        return resolution.events;
      },
      publish(receipt, event) {
        publishFragrantDeathWave(resolution.world, receipt, event);
      },
    });
  })();

  constructor(
    private readonly world: World,
    private readonly events: GameEvent[],
    private readonly toolGateway: ToolGateway,
    private readonly eventRegistry: EventRegistry,
    private readonly state: RuntimeSnapshot,
    private readonly config?: ReadonlyBoardConfig,
  ) {}

  /**
   * 初始波完成标死和必要发布后，再收遗言、交警徽、逐角色处理死亡动作；追加目标先同步标死，
   * 下一波再处理其死后动作。来源昼夜与动作执行阶段分别保存，不能用当前阶段覆盖夜间来源。
   * 当前性撤销可提前返回，异常保留已提交前缀；是否继续阶段或封盘仍由 PhaseManager 决定。
   */
  async resolve(
    deadIds: EntityId[],
    sources: DeathSources,
    actionProvider: ActionProvider,
    phase: Phase,
    lastWordsPhase: Phase,
    deathPhases: Readonly<Record<EntityId, Phase>> = {},
    nightEffects?: {
      dreams?: DreamNightEffects;
      blocksPassiveNightShot?: (targetId: EntityId) => boolean;
      nightOriginIds?: readonly EntityId[];
      isCurrent?: () => boolean;
      onInitialWaveCommitted?: (
        deaths: readonly EntityId[],
        sources: DeathSources | undefined,
        receipt: DeathCommitReceipt,
      ) => GameEvent;
      originalLives?: ReadonlyMap<EntityId, DeathOriginalLife>;
      poisonRoutes?: readonly NightPoisonRoute[];
      animalUnit?: object;
      execution?: DeathExecutionContext;
    },
  ): Promise<void> {
    const resolutionPhase = this.state.phase;
    const resolutionDay = this.state.day;
    const lastWordsPolicy = this.config?.lastWords?.policy ?? "awa_initial_wave_v1";
    const revealPolicy = this.config?.disclosure?.deathRevealPolicy ?? "awa_hidden_v1";
    const ownsFragrant = isFragrantPairBoard(this.world);
    const isCurrent = () =>
      this.state.phase === resolutionPhase &&
      this.state.day === resolutionDay &&
      !this.state.gameOver &&
      (nightEffects?.isCurrent?.() ?? true) &&
      (!ownsFragrant || !!fragrantAuthoritySnapshot(this.world));
    const revealCurrent = () =>
      revealPolicy === "netease_2017_open_v1" &&
      this.config?.disclosure?.deathRevealPolicy === revealPolicy;
    const lastWordsCurrent = () =>
      isCurrent() && (this.config?.lastWords?.policy ?? "awa_initial_wave_v1") === lastWordsPolicy;
    const resolution = this;
    const animalDeathWave = AnimalDeathWavePreparation.fromRuntime(
      {
        get world() {
          return resolution.world;
        },
        get events() {
          return resolution.events;
        },
      },
      resolutionDay,
      nightEffects,
      isCurrent,
    );
    const ownsAnimal = animalDeathWave.enabled;
    const preparedSources: DeathSources = structuredClone(sources);
    // 普通静态输入在任何角色事实前完成整波预检；getter／Proxy 仍沿旧表达式惰性读取。
    preflightDeathWaveData(deadIds, preparedSources, deathPhases);
    deadIds = animalDeathWave.prepare(deadIds, preparedSources, phase);
    // seen 追踪本次结算已纳入的席位；DeathCommitter 的账本另按原体及版本判断已结算生命。
    const seen = new Set<EntityId>(
      deadIds.filter((id) => {
        return (
          this.world.getComponent(id, COMPONENT.Alive) !== undefined &&
          !this.deathCommitter.isSettledLife(id)
        );
      }),
    );
    let pending = [...seen];
    const allSources: DeathSources = preparedSources;
    const nativeHunterShotTargets = new Set<EntityId>();
    const initialPhases: Record<EntityId, Phase> = structuredClone(deathPhases);
    const nightOrigin = new Set(nightEffects?.nightOriginIds ?? []);
    if (!isCurrent()) return;
    // 关系闭包先于标死、遗言和枪权判断；恋人／婚约追加的抑制死因不能等死亡 hook 后再补。
    const weddingInitial = this.weddingDeathWave.expand(pending, allSources, seen, nightOrigin);
    const linkedInitial = expandLoversWave(
      this.world,
      pending,
      allSources,
      this.events,
      nightOrigin,
      seen,
      nightEffects?.dreams,
    );
    for (const id of [...linkedInitial, ...weddingInitial]) {
      seen.add(id);
      initialPhases[id] = nightOrigin.has(id) ? Phase.Night : phase;
    }
    const fragrantInitial = ownsFragrant
      ? prepareFragrantDeathWave(this.world, resolutionDay, pending)
      : null;
    const fragrantRootPhase = fragrantInitial
      ? (initialPhases[fragrantInitial.rootId] ??
        (nightOrigin.has(fragrantInitial.rootId) ? Phase.Night : phase))
      : phase;
    if (fragrantInitial?.addedTargetId !== null && fragrantInitial?.addedTargetId !== undefined) {
      const id = fragrantInitial.addedTargetId;
      pending.push(id);
      seen.add(id);
      allSources[id] = [DeathCause.FragrantLink];
      initialPhases[id] = fragrantRootPhase;
      if (fragrantRootPhase === Phase.Night) nightOrigin.add(id);
    }
    const originPhases = new Map(
      pending.map((id) => [id, initialPhases[id] ?? (nightOrigin.has(id) ? Phase.Night : phase)]),
    );
    const publicLinkedInitial = [
      ...linkedInitial,
      ...(phase === Phase.Night ? [] : weddingInitial),
    ];
    if (publicLinkedInitial.length && !ownsFragrant)
      this.events.push({
        timestamp: Date.now(),
        type: "additional_deaths",
        payload: { deaths: publicLinkedInitial },
      });
    const initialUnit = openDeathWave("initial", resolutionDay, resolutionPhase, deathExecutionContext(nightEffects));
    let pendingUnits: readonly DeathWaveUnit[] = [initialUnit];
    let previousCommits: readonly DeathCommitReceipt[] = [];
    let firstBatch = true;
    let fragrantInitialCommitted = false;
    // 只收集原实例，在原 finally 位置尝试过期；先取消未提交双生波凭据，取消失败时过期尚未执行。
    // 已付款和死亡不回滚，不为统一清理吞掉原取消异常。
    const gunsToExpire: ReturnType<typeof firstDeathGuns> = [];

    try {
      // 空初始波仍执行原发布回调；空条目凭证只关联这次发布，不证明枪付款或整个死亡链完成。
      if (pending.length === 0 && nightEffects?.onInitialWaveCommitted && isCurrent()) {
        const receipt = new DeathCommitReceipt(
          planDeathWave(
            [],
            {},
            "initial",
            originPhases,
            deathWaveOriginalLives(nightEffects),
            deathWavePoisonMetadata(nightEffects),
            pendingUnits,
          ),
          Object.freeze([]),
        );
        const event = nightEffects.onInitialWaveCommitted([], {}, receipt);
        receipt.recordPublication(event, []);
      }
      while (pending.length > 0) {
        if (!isCurrent()) return;
        const deathPhase = firstBatch ? phase : this.state.phase;
        // 初始波整批标死；追加目标已在前一角色回调标死，再访仍执行原收尾，但不重复首次生命事实。
        const receipt = this.deathCommitter.markPlayersDead(
          pending,
          true,
          gunsToExpire,
          revealPolicy === "netease_2017_open_v1",
          allSources,
          nightEffects?.animalUnit ?? isCurrent,
          planDeathWave(
            pending,
            allSources,
            firstBatch ? "initial" : "revisit",
            originPhases,
            deathWaveOriginalLives(nightEffects),
            deathWavePoisonMetadata(nightEffects),
            pendingUnits,
            previousCommits,
          ),
        );
        if (firstBatch && fragrantInitial) {
          commitFragrantDeathWave(this.world, fragrantInitial);
          fragrantInitialCommitted = true;
        }
        // 后续枪波已在枪回调逐目标标死并记录；这里不再重复双生发布。
        if (ownsFragrant && firstBatch)
          this.fragrantDeathWave.recordCommittedWave(
            firstBatch ? fragrantInitial : null,
            pending,
            allSources,
            originPhases,
            firstBatch,
          );
        // 此处生命及账本已提交；发布回调抛错不撤销死亡，凭证只把原事件与提交条目关联。
        if (firstBatch && nightEffects?.onInitialWaveCommitted) {
          const event = nightEffects.onInitialWaveCommitted(pending, allSources, receipt);
          receipt.recordPublication(event, pending);
          this.fragrantDeathWave.publishVisibleWave(fragrantInitial, event);
        }
        if (ownsAnimal && firstBatch)
          animalDeathWave.recordInitialWave(pending, allSources, deathPhase);
        if (
          firstBatch &&
          fragrantInitial?.addedTargetId !== null &&
          fragrantInitial?.addedTargetId !== undefined
        ) {
          const event: GameEvent = {
            timestamp: Date.now(),
            type: "additional_deaths",
            payload: { deaths: [fragrantInitial.addedTargetId] },
          };
          this.events.push(event);
          receipt.recordPublication(event, [fragrantInitial.addedTargetId]);
          this.fragrantDeathWave.publishVisibleWave(fragrantInitial, event);
        }
        // 整波角色扩展先看到已提交死亡，随后记录梦链，再按政策授予并收集遗言。
        this.eventRegistry.onCommittedDeathWave(
          this.world,
          pending,
          allSources,
          resolutionDay,
          deathPhase,
          this.events,
        );
        nightEffects?.dreams?.recordDeaths(pending, this.events);
        // 基础政策只考察初始波；网易具名政策还考察追加波，逐人昼夜与死因资格仍由遗言机制核对。
        if (
          (firstBatch || lastWordsPolicy === "netease_2017_day_and_first_night_v1") &&
          lastWordsCurrent()
        ) {
          const wordsPhases = firstBatch
            ? initialPhases
            : Object.fromEntries(
                pending.map((id) => [id, nightOrigin.has(id) ? Phase.Night : deathPhase]),
              );
          const wordsContext: LastWordsGrantContext | undefined = ownsFragrant
            ? { policy: FRAGRANT_PAIR_POLICY, initialWave: firstBatch }
            : undefined;
          this.lastWordsMechanism.recordLastWordsGranted(
            this.world,
            pending,
            phase,
            lastWordsPhase,
            this.state.day,
            this.events,
            allSources,
            wordsPhases,
            lastWordsPolicy,
            wordsContext,
          );
          await this.collectLastWords(
            pending,
            lastWordsPhase,
            phase,
            allSources,
            actionProvider,
            wordsPhases,
            lastWordsCurrent,
            lastWordsPolicy,
            wordsContext,
          );
        }
        if (!isCurrent()) return;

        // 先处理警长死亡带来的警徽逻辑，再执行角色死亡钩子。
        for (const deadId of pending) {
          const causes = allSources[deadId] ?? [];
          const actualDeathPhase = firstBatch ? (initialPhases[deadId] ?? deathPhase) : deathPhase;
          const reason = causes.includes(DeathCause.SelfDestruct)
            ? "self_destruct"
            : causes.includes(DeathCause.Exile)
              ? "voted_out"
              : `${actualDeathPhase}_death`;
          await resolveSheriffBadge(
            this.world,
            deadId,
            reason,
            this.events,
            this.toolGateway,
            actionProvider,
            resolutionPhase,
            resolutionDay,
            isCurrent,
          );
          if (!isCurrent()) return;
        }

        const next = new Set<EntityId>();
        const nextCommits: DeathCommitReceipt[] = [];
        const nextUnits: DeathWaveUnit[] = [];
        for (const deadId of pending) {
          if (!isCurrent()) return;
          // 来源阶段属于这次死亡；黎明后处理夜间死亡仍必须保留夜间枪权／关系保护规则。
          const sourcePhase =
            originPhases.get(deadId) ?? (nightOrigin.has(deadId) ? Phase.Night : deathPhase);
          const actions: DeathWaveActions = {
            phase: resolutionPhase,
            day: resolutionDay,
            permits: [],
            isCurrent,
          };
          try {
            await this.eventRegistry.onDeath(
              this.world,
              [deadId],
              allSources,
              (actorId, abilityId) =>
                this.collectDeathShot(
                  actorId,
                  firstBatch ? (initialPhases[actorId] ?? deathPhase) : deathPhase,
                  sourcePhase,
                  allSources,
                  actionProvider,
                  actions,
                  abilityId,
                  nightOrigin.has(actorId) && !(firstBatch && initialPhases[actorId] === Phase.Day),
                ),
              this.events,
              // 每个成功钩子提案同步进入这里；后面的钩子可见已标死目标，失败不丢弃先前提交。
              (result) => {
                if (!isCurrent()) return;
                const proposed = [...result.extraDeaths],
                  proposedSources = structuredClone(result.extraDeathSources),
                  nightTargets = [...(result.nightEffectTargets ?? [])];
                preflightDeathWaveData(proposed, proposedSources);
                preflightDeathWaveData(nightTargets, {});
                const additionalUnit = openDeathWave("additional", resolutionDay, resolutionPhase, deathExecutionContext(nightEffects));
                const shots = new Map(
                  (result.pendingShots ?? []).map((shot) => [shot.targetScope.id, shot]),
                );
                // 旧目标或已撤权的枪只移除自己的 Shot 原因；其它独立原因仍可进入实际死亡提交。
                for (const [id, shot] of shots) {
                  if (livingNightLife(this.world, shot.targetScope) && (shot.isCurrent?.() ?? true))
                    continue;
                  proposedSources[id] = (proposedSources[id] ?? []).filter(
                    (cause) => cause !== DeathCause.Shot,
                  );
                  if (!proposedSources[id].length) {
                    const index = proposed.indexOf(id);
                    if (index >= 0) proposed.splice(index, 1);
                  }
                  if (!proposedSources[id].length)
                    for (let i = nightTargets.length - 1; i >= 0; i--)
                      if (nightTargets[i] === id) nightTargets.splice(i, 1);
                  shots.delete(id);
                }
                const linked = new Set<EntityId>(),
                  publicLinked: EntityId[] = [];
                let newlyMarked = false;
                const marked: number[] = [];
                const additionalReceipts: DeathCommitReceipt[] = [];
                // 每个 hook 的贡献在原准备点同步完成；描述只影响追加原因和公开关联，不授予标死权限。
                const resolution = this;
                const preparedContributions = (result.deathWaveContributions ?? []).map(
                  (contribution) =>
                    contribution.prepare(
                      {
                        get world() {
                          return resolution.world;
                        },
                        get events() {
                          return resolution.events;
                        },
                        blocksNightLinkedDeath: (target) =>
                          nightEffects?.dreams?.blocksNightCharm(this.world, target(), seen),
                      },
                      proposed,
                      proposedSources,
                      nightTargets,
                      allSources,
                      nativeHunterShotTargets,
                      seen,
                    ),
                );
                const contributedCauses = new Map<EntityId, readonly DeathCause[]>();
                const publicContributionTargets = new Set<EntityId>();
                for (const contribution of preparedContributions)
                  for (const linkedDeath of contribution.linkedDeaths) {
                    contributedCauses.set(linkedDeath.targetId, [
                      ...new Set([
                        ...(contributedCauses.get(linkedDeath.targetId) ?? []),
                        ...linkedDeath.addedCauses,
                      ]),
                    ]);
                    if (linkedDeath.publicAdditionalDeath)
                      publicContributionTargets.add(linkedDeath.targetId);
                  }
                for (const id of nightTargets) nightOrigin.add(id);
                if (nightEffects?.dreams && nightTargets.length)
                  for (const id of nightEffects.dreams.linkedDeaths(
                    this.world,
                    nightTargets,
                    new Set(Object.keys(allSources).map(Number)),
                  )) {
                    linked.add(id);
                    if (!proposed.includes(id)) proposed.push(id);
                    proposedSources[id] = [
                      ...new Set([...(proposedSources[id] ?? []), DeathCause.Dream]),
                    ];
                    nightOrigin.add(id);
                  }
                this.weddingDeathWave.expand(proposed, proposedSources, seen, nightOrigin);
                expandLoversWave(
                  this.world,
                  proposed,
                  proposedSources,
                  this.events,
                  nightOrigin,
                  seen,
                  nightEffects?.dreams,
                );
                const fragrantRoots = ownsFragrant
                  ? proposed.filter(
                      (id) =>
                        !next.has(id) &&
                        !seen.has(id) &&
                        !this.deathCommitter.isSettledLife(id) &&
                        this.world.getComponent(id, COMPONENT.Alive)?.alive,
                    )
                  : [];
                const fragrantGun = ownsFragrant
                  ? prepareFragrantDeathWave(this.world, resolutionDay, fragrantRoots)
                  : null;
                if (
                  fragrantGun?.addedTargetId !== null &&
                  fragrantGun?.addedTargetId !== undefined
                ) {
                  proposed.push(fragrantGun.addedTargetId);
                  proposedSources[fragrantGun.addedTargetId] = [DeathCause.FragrantLink];
                }
                let fragrantGunCommitted = false;
                try {
                  // 枪造成的追加波逐目标提交：后一个失败时，前一个的死亡、事实和库存仍有效。
                  for (const id of proposed) {
                    if (next.has(id)) {
                      allSources[id] = [
                        ...new Set([...(allSources[id] ?? []), ...(proposedSources[id] ?? [])]),
                      ];
                      continue;
                    }
                    if (seen.has(id) || this.deathCommitter.isSettledLife(id)) {
                      if ((proposedSources[id] ?? []).includes(DeathCause.Lovers))
                        allSources[id] = [
                          ...new Set([...(allSources[id] ?? []), DeathCause.Lovers]),
                        ];
                      if (linked.has(id))
                        allSources[id] = [
                          ...new Set([...(allSources[id] ?? []), DeathCause.Dream]),
                        ];
                      if (contributedCauses.has(id))
                        allSources[id] = [
                          ...new Set([...(allSources[id] ?? []), ...contributedCauses.get(id)!]),
                        ];
                      continue;
                    }
                    if (!this.world.getComponent(id, COMPONENT.Alive)) continue;
                    if (
                      ownsAnimal &&
                      !animalDeathWave.prepare([id], proposedSources, sourcePhase).includes(id)
                    )
                      continue;
                    let shot = shots.get(id);
                    if (
                      shot &&
                      (!livingNightLife(this.world, shot.targetScope) ||
                        (!fragrantGun && shot.isCurrent?.() === false))
                    ) {
                      proposedSources[id] = (proposedSources[id] ?? []).filter(
                        (cause) => cause !== DeathCause.Shot,
                      );
                      shots.delete(id);
                      shot = undefined;
                      if (!proposedSources[id].length) continue;
                    }
                    seen.add(id);
                    allSources[id] = [...new Set(proposedSources[id] ?? [])];
                    originPhases.set(id, ownsFragrant ? this.state.phase : sourcePhase);
                    const commitIds = [id];
                    const receipt = this.deathCommitter.markPlayersDead(
                      commitIds,
                      false,
                      gunsToExpire,
                      revealCurrent(),
                      allSources,
                      nightEffects?.animalUnit ?? isCurrent,
                      planDeathWave(
                        commitIds,
                        allSources,
                        "additional",
                        originPhases,
                        shot ? new Map([[id, shot.targetScope]]) : undefined,
                        [],
                        [additionalUnit],
                      ),
                    );
                    additionalReceipts.push(receipt);
                    nextCommits.push(receipt);
                    if (ownsAnimal)
                      animalDeathWave.recordAdditionalDeath(id, allSources, sourcePhase);
                    newlyMarked = true;
                    marked.push(id);
                    // 枪资源由角色钩子消费；这里在目标实际标死后发布命中，事件关联不再次付款。
                    if (shot) {
                      if (shot.event.type === "hunter_shot") nativeHunterShotTargets.add(id);
                      this.events.push(shot.event);
                      receipt.recordPublication(shot.event, [id]);
                    }
                    if (
                      publicContributionTargets.has(id) ||
                      (linked.has(id) && !result.extraDeaths.includes(id)) ||
                      (!shot && !(proposedSources[id] ?? []).includes(DeathCause.Shot))
                    )
                      publicLinked.push(id);
                    next.add(id);
                  }
                  if (newlyMarked) {
                    nextUnits.push(additionalUnit);
                    if (fragrantGun) {
                      commitFragrantDeathWave(this.world, fragrantGun);
                      fragrantGunCommitted = true;
                    }
                    if (ownsFragrant)
                      this.fragrantDeathWave.recordCommittedWave(
                        fragrantGun,
                        marked,
                        allSources,
                        originPhases,
                        false,
                      );
                    // 已提交死亡和必需关系贡献之后，沿原次序逐角色检查继承；失败保留该前缀。
                    refreshWolfKnifeInheritanceAtCheckpoint({
                      world: () => this.world,
                      events: () => this.events,
                      day: () => this.state.day,
                    });
                  }
                  if (publicLinked.length) {
                    const event: GameEvent = {
                      timestamp: Date.now(),
                      type: "additional_deaths",
                      payload: { deaths: publicLinked },
                    };
                    this.events.push(event);
                    for (const receipt of additionalReceipts)
                      receipt.recordPublication(
                        event,
                        publicLinked.filter((id) => receipt.committed(id) !== undefined),
                      );
                    this.fragrantDeathWave.publishVisibleWave(fragrantGun, event);
                  }
                  // 只在原标死／公开追加事实之后交回本族发布；异常保留前缀并阻止后续 hook。
                  for (const contribution of preparedContributions)
                    contribution.publishAfterDeaths();
                  nightEffects?.dreams?.recordDeaths([...next, ...linked], this.events);
                  for (const permit of actions.permits.splice(0)) permit.close();
                } finally {
                  if (fragrantGun && !fragrantGunCommitted)
                    cancelFragrantDeathWave(this.world, fragrantGun);
                }
              },
              Object.freeze({
                day: resolutionDay,
                nativeHunterShotTargets,
                deferShotCommit: true,
                deathOriginPhase: sourcePhase,
                nightEffect: nightOrigin.has(deadId),
                blocksNightShot: (targetId: EntityId) =>
                  (nightEffects?.blocksPassiveNightShot?.(targetId) ?? false) ||
                  (nightEffects?.dreams?.blocksNightShot(this.world, targetId) ?? false),
                blocksNightCharm: (targetId: EntityId) =>
                  nightEffects?.dreams?.blocksNightCharm(this.world, targetId, seen) ?? false,
                eligibleDead: seen,
                isCurrent,
              }),
            );
          } finally {
            for (const permit of actions.permits) permit.close();
          }
        }

        // Set 保留追加目标首次加入顺序；再访沿用真实提案单位及成功凭证，不重新制造波次来源。
        pending = [...next];
        pendingUnits = nextUnits;
        previousCommits = nextCommits;
        firstBatch = false;
      }
    } finally {
      if (fragrantInitial && !fragrantInitialCommitted)
        cancelFragrantDeathWave(this.world, fragrantInitial);
      finishDeathGuns(gunsToExpire, this.events);
    }
  }

  /** 收集枪的选择而非消费弹药或杀死目标；窗口绑定原生命，回复和校验后仍须复核当前性。 */
  private async collectDeathShot(
    actorId: EntityId,
    deathPhase: Phase,
    deathOriginPhase: Phase,
    sources: DeathSources,
    actionProvider: ActionProvider,
    actions: DeathWaveActions,
    abilityId?: string,
    nightExchange: boolean = false,
  ): Promise<DeathShotSelection> {
    if (deathPhase === Phase.Night && nightmareFearBlocks(this.world, actorId, actions.day, true))
      return { kind: "invalid" };
    const isCurrent = () =>
      actions.isCurrent() &&
      this.state.phase === actions.phase &&
      this.state.day === actions.day &&
      !this.state.gameOver;
    // 只装配延迟查询，不提前读取 World／日期；资格 owner 在原 callee 和参数时点捕获。
    const resolution = this;
    const qualification = captureDeathShotEligibility(
      {
        get world() { return resolution.world; },
        get day() { return actions.day; },
        get demonHunterNativeGunCurrent() { return demonHunterNativeGunCurrent; },
      },
      actorId,
      abilityId,
      sources,
      deathOriginPhase,
      isCurrent,
    );
    if (!qualification) return { kind: "invalid" };
    const { nativePolicy, permissionCurrent, eligible } = qualification;
    if (!eligible()) return { kind: "invalid" };
    const permit = this.world.openDeathAction(
      actorId,
      "shoot",
      actions.phase,
      actions.day,
      permissionCurrent,
      abilityId,
    );
    actions.permits.push(permit);
    const requests = new GameActionRequestFactory(this.world, this.events, actions.day);
    for (let attempt = 1; attempt <= 3; attempt++) {
      // 每次重试重新捕获候选生命；同一编号复活或替换组件后，上一轮回复不能命中新生命。
      const targets = new Map(
        this.world.getAliveEntityIds().map((id) => [id, captureNightLife(this.world, id)]),
      );
      if (!eligible()) return { kind: "invalid" };
      const request = requests.create({
        phase: actions.phase,
        actorId: actorId,
        allowedTools: ["shoot"],
        stage:
          abilityId === undefined &&
          this.world.getComponent(actorId, COMPONENT.Role)?.role === Role.Hunter
            ? "hunter_shot"
            : "death_shot",
        requiresAction: true,
        summary: { key: "request.summary.death_shot" },
        context: {
          ...(this.config?.magician ||
          this.config?.evilKnight ||
          abilityId !== undefined ||
          this.world.getComponent(actorId, COMPONENT.Role)?.role === Role.AwakenedHiddenWolf
            ? { action_failure_policy: "error" as const, allow_fallback: false }
            : {}),
          ...(abilityId === undefined ? {} : { ability_id: abilityId }),
          trigger: "on_death",
          death_phase: deathPhase,
          ...(nativePolicy === "awa_day_deaths_v1" ? { death_origin_phase: deathOriginPhase } : {}),
          death_sources: [...(sources[actorId] ?? [])],
          death_action_id: permit.id,
          shoot_candidates: [...targets.keys()].filter((id) => id !== actorId),
          ...(attempt === 1 ? {} : { retry_attempt: attempt - 1, retry_max: 2 }),
        },
      });
      if (!eligible()) return { kind: "invalid" };
      if (this.config?.magician) assertMagicianRosterCurrent(this.world);
      const action = await actionProvider.getAction(request);
      if (this.config?.magician) assertMagicianRosterCurrent(this.world);
      if (
        !eligible() ||
        !this.world.hasDeathAction(
          actorId,
          "shoot",
          actions.phase,
          actions.day,
          permit.id,
          abilityId,
        )
      )
        return { kind: "invalid" };
      if (action?.name !== "shoot") {
        if (this.config?.magician) throw new Error("magician_shot_action_missing");
        if (this.config?.evilKnight) throw new Error("evil_knight_hunter_action_missing");
        continue;
      }
      const validated = this.toolGateway.validateAndSanitize(this.world, actorId, action, {
        phase: actions.phase,
        day: actions.day,
        deathActionId: permit.id,
        abilityId,
      });
      if (
        !eligible() ||
        !this.world.hasDeathAction(
          actorId,
          "shoot",
          actions.phase,
          actions.day,
          permit.id,
          abilityId,
        )
      )
        return { kind: "invalid" };
      if (!validated.ok || !validated.sanitizedCall) {
        if (this.config?.magician) throw new Error("magician_shot_action_invalid");
        if (this.config?.evilKnight) throw new Error("evil_knight_hunter_action_invalid");
        continue;
      }
      const targetId = validated.sanitizedCall.args.target_id;
      // 空枪也只是已授权选择，真正消耗留给随后处理该选择的角色钩子。
      if (targetId === null) return { kind: "pass", deathActionId: permit.id };
      const targetScope = targets.get(targetId);
      if (!targetScope || !livingNightLife(this.world, targetScope)) {
        if (this.config?.magician) throw new Error("magician_shot_target_stale");
        continue;
      }
      if (nightExchange && isMagicianBoard(this.world)) {
        const mapped = resolveMagicianNightTarget(this.world, actions.day, targetId, "death_shot");
        if (!mapped.isCurrent()) throw new Error("magician_shot_target_stale");
        return {
          kind: "shot",
          targetId: mapped.effectiveId,
          deathActionId: permit.id,
          targetScope: mapped.scope,
          mappingCurrent: mapped.isCurrent,
          ...(!mapped.scope.life.alive ? { mappedMiss: true as const } : {}),
        };
      }
      return { kind: "shot", targetId, deathActionId: permit.id, targetScope };
    }
    if (abilityId !== undefined && eligible()) throw new Error("gift_gun_valid_action_missing");
    return { kind: "invalid" };
  }

  /** 授予事实不替代发言窗口；每位死者等待回复后复核阶段、日期、终局与原生命许可，再写发言。 */
  private async collectLastWords(
    deadIds: EntityId[],
    phase: Phase,
    deathPhase: Phase,
    sources: DeathSources,
    actionProvider: ActionProvider,
    deathPhases: Readonly<Record<EntityId, Phase>>,
    scopeCurrent: () => boolean = () => true,
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    wordsContext?: LastWordsGrantContext,
  ): Promise<void> {
    const requests = new GameActionRequestFactory(this.world, this.events, this.state.day);
    const day = this.state.day;
    for (const deadId of deadIds) {
      const actualDeathPhase = deathPhases[deadId] ?? deathPhase;
      if (
        !this.lastWordsMechanism.shouldGrantLastWords(
          actualDeathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          wordsContext,
        )
      )
        continue;
      if (
        !scopeCurrent() ||
        this.state.phase !== phase ||
        this.state.day !== day ||
        this.state.gameOver
      )
        return;
      const permit = this.world.openDeathAction(deadId, "speak", phase, day, scopeCurrent);
      try {
        const request = requests.create({
          phase,
          actorId: deadId,
          allowedTools: ["speak"],
          stage: "last_words",
          requiresAction: true,
          summary: { key: "request.summary.last_words" },
          context: {
            trigger: "last_words",
            death_phase: actualDeathPhase,
            death_action_id: permit.id,
          },
        });
        if (!scopeCurrent() || !this.world.hasDeathAction(deadId, "speak", phase, day, permit.id))
          return;
        const action = await actionProvider.getAction(request);
        if (
          !scopeCurrent() ||
          this.state.phase !== phase ||
          this.state.day !== day ||
          this.state.gameOver ||
          !this.world.hasDeathAction(deadId, "speak", phase, day, permit.id)
        )
          return;
        if (action?.name !== "speak") {
          continue;
        }
        const validated = this.toolGateway.validateAndSanitize(this.world, deadId, action, {
          phase,
          day: this.state.day,
          deathActionId: permit.id,
        });
        if (!validated.ok || !validated.sanitizedCall) {
          continue;
        }
        if (
          !scopeCurrent() ||
          this.state.phase !== phase ||
          this.state.day !== day ||
          this.state.gameOver ||
          !this.world.hasDeathAction(deadId, "speak", phase, day, permit.id)
        )
          return;
        this.events.push({
          timestamp: Date.now(),
          type: "last_words_spoken",
          payload: {
            playerId: deadId,
            phase,
            day: this.state.day,
            text: validated.sanitizedCall.args.text,
          },
        });
      } finally {
        permit.close();
      }
    }
  }
}

/**
 * 提供梦魇绑定的恐惧资格、普通狼刀目标及原状态读取查询。
 * 输入是玩家／日期、候选序号或原角色；输出保留原恐惧谓词、狼行动政策及同一可读状态绑定。
 * 绑定只捕获原 World 引用，不提前读组件或返回 World、状态写者、夜间开启或效果提交方法。
 * 名单复验公开同一原函数，供夜间规则组合及阶段检查点读取，不改其原名单撤销；
 * 查询时仍传播原名单撤销与目标生命失败；板子谓词保持原只读绑定及调用方重复参数的读取顺序。
 */
import type { EntityId } from "../../../../core/domain/model";
import { Role } from "../../../../core/domain/identity";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
import { nightmareFearBlocks } from "./night_frame";
export { isNightmareBoard, nightmareKnifeBlocked, assertNightmareRosterCurrent } from "./night_frame";
import { getNightmareShadowState } from "./state";

export interface NightmareNightEligibility {
  blocks(actorId: EntityId, day: number): boolean;
}

export function bindNightmareNightEligibility(world: World): NightmareNightEligibility {
  return Object.freeze({
    blocks: (actorId: EntityId, day: number) => nightmareFearBlocks(world, actorId, day),
  });
}

export interface NightmareKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

export function bindNightmareKnifeTargetQuery(world: World): NightmareKnifeTargetQuery {
  return Object.freeze({
    allows: (targetId: EntityId) =>
      world.getComponent(targetId, COMPONENT.Role)?.role !== Role.NightmareShadow ||
      getNightmareShadowState(world.getComponent(targetId, COMPONENT.Role))?.wolfActionPolicy ===
        "standard",
  });
}

export { getNightmareShadowState } from "./state";

/**
 * 负责死亡枪资格的完整捕获与晚复验：原赠枪、原生库存／政策／死因身份及猎魔人原体查询。
 * 输入为原 actor／ability／来源、来源阶段、惰性 World／日期和原当前性回调；
 * 输出为缺失赠枪的 null，或原政策及 permissionCurrent／eligible 函数引用。
 * 本模块不打开行动许可、消费弹药、选择目标、标死或发布事件；数据与回调不是 JSON 授权。
 * 原生 Hunter 身份在赠枪路径也保留；Demon→枪→原生政策→canShoot 的短路顺序不变。
 */
import { Role, type EntityId, type DeathSources, type Phase, type DeathActionPolicy } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { World } from "../../../core/domain/world";
import { permitsDeathShot } from "../../../core/domain/deaths";
import { activeDeathGun, captureDeathGun } from "./death-gun-lifecycle";
import { getHunterState } from "./hunter/ports";
import { getWolfKingState } from "./wolf_king/ports";
import type { demonHunterNativeGunCurrent } from "./demon_hunter/ports";

/** 只读运行查询；生产 getter 晚读原字段及原命令，不冻结 World 或复制生命／枪权。 */
interface DeathShotEligibilityRuntime {
  readonly world: World;
  readonly day: number;
  readonly demonHunterNativeGunCurrent: typeof demonHunterNativeGunCurrent;
}

/** 只捕获原比较基准与函数，后续请求／await 前后仍在原调用点复验；不是新的许可或库存。 */
export interface DeathShotEligibility {
  readonly nativePolicy: DeathActionPolicy;
  readonly permissionCurrent: () => boolean;
  readonly eligible: () => boolean;
}

export function captureDeathShotEligibility(
  runtime: DeathShotEligibilityRuntime,
  actorId: EntityId,
  abilityId: string | undefined,
  sources: DeathSources,
  deathOriginPhase: Phase,
  isCurrent: () => boolean,
): DeathShotEligibility | null {
  const gun =
    abilityId === undefined
      ? undefined
      : activeDeathGun(runtime.world, actorId, abilityId, runtime.day, true);
  if (abilityId !== undefined && !gun) return null;
  const role = runtime.world.getComponent(actorId, COMPONENT.Role);
  const nativeState =
    abilityId === undefined && role
      ? role.role === Role.Hunter
        ? getHunterState(role)
        : role.role === Role.WolfKing
          ? getWolfKingState(role)
          : undefined
      : undefined;
  const nativeHunter = role?.role === Role.Hunter;
  const nativePolicy = nativeState?.deathActionPolicy ?? "awa_qualified_sources_v1";
  const causeIdentity = JSON.stringify(sources[actorId] ?? []);
  const nativeCurrent = () =>
    !nativeState ||
    (runtime.world.getComponent(actorId, COMPONENT.Role) === role &&
      (role?.role === Role.Hunter
        ? getHunterState(role)
        : role?.role === Role.WolfKing
          ? getWolfKingState(role)
          : undefined) === nativeState &&
      (nativeState.deathActionPolicy ?? "awa_qualified_sources_v1") === nativePolicy &&
      JSON.stringify(sources[actorId] ?? []) === causeIdentity &&
      permitsDeathShot(sources[actorId] ?? [], nativePolicy, deathOriginPhase));
  const gunCurrent = gun
    ? captureDeathGun(runtime.world, actorId, gun, runtime.day, isCurrent).isEligible
    : isCurrent;
  // 仅在原 nativeHunter 分支取得同一查询并裸调用；赠枪的 Hunter 身份也不能跳过此复验。
  const demonNativeCurrent = () => {
    const query = runtime.demonHunterNativeGunCurrent;
    return query(runtime.world, actorId);
  };
  const permissionCurrent = () =>
    (!nativeHunter || demonNativeCurrent()) &&
    gunCurrent() &&
    nativeCurrent();
  const eligible = () => permissionCurrent() && (!nativeState || nativeState.canShoot);
  return { nativePolicy, permissionCurrent, eligible };
}

/**
 * 负责赠枪的公开查询／生命周期入口、玩家投影及工具枪权政策装配。
 * 输入为原实例或 gateway 校验上下文；输出保留真实函数引用、裁剪后的玩家 DTO 与拒绝代码。
 * 实例生命周期和原体证明归 death-gun-lifecycle，玩家投影归 player_state，公共类型归 game-contract。
 * 本入口仅在原参数位置查询枪权；不修改库存、标记死亡、复制运行时授权或执行录制 I/O。
 */
import { RuleError } from "@ai-werewolf-arena/game-contract";
import type { ValidationRuleContext } from "../validation/contracts";
import { validateDeathShot } from "./death_shot";
import { activeDeathGun } from "./death-gun-lifecycle";
export {
  allDeathGuns,
  findDeathGun,
  deathGunOwnerCurrent,
  grantDeathGun,
  armDeathGun,
  activeDeathGun,
  captureDeathGun,
  firstDeathGuns,
  finishDeathGuns,
  setDeathGunEnabled,
  transferDeathGun,
  consumeDeathGunShot,
} from "./death-gun-lifecycle";
export { projectDeathGun } from "./player_state";


export function copyDeathGun(): never {
  throw new Error("death_ability_copy_not_supported");
}

export function validateGiftGun(ctx: ValidationRuleContext) {
  if (!ctx.abilityId || ctx.day === undefined) return { code: RuleError.ShootUnavailable };
  return validateDeathShot(
    ctx,
    !!activeDeathGun(ctx.world, ctx.actorId, ctx.abilityId, ctx.day, true),
  );
}

/** 完整资格组合的实际公开 owner；不包装调用或改变原赠枪工具校验。 */
export { captureDeathShotEligibility } from "./death-shot-eligibility";
export type { DeathShotEligibility } from "./death-shot-eligibility";

/**
 * 负责赠枪实例的授予、武装、转移、首次死亡收尾以及原体授权。
 * 输入为所属 World、原角色／生命／库存实例和明确业务夜时点；输出为同引用只读实例、
 * 捕获资格和原资源事实。owners/counters 是原唯一状态，不复制为第二份实例仓库。
 * 仅写 deathAbilities、retiredDeathAbilityIds 及本枪资源；不执行死亡、枪目标选择或录制 I/O。
 * 已付前缀和原 getter／提交顺序保持，替身或复活不能重新获得首次死亡枪权。
 */
import type { DeathGun, DeathGunReadView } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { Camp, type EntityId, type GameEvent } from "../../../core/domain/model";
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { World } from "../../../core/domain/world";
import { projectDeathGun } from "./player_state";

// 原体证明捕获原 World、角色、private 容器、生命版本及来源；相同字符串 ID 不构成授权。
interface GunOwner {
  world: World;
  actorId: number;
  role: RoleComponent;
  roleKind: RoleComponent["role"];
  camp: Camp;
  privateState: RoleComponent["privateState"];
  life: AliveComponent;
  version: number;
  id: string;
  source: DeathGunReadView["source"];
  sourceKind: DeathGun["source"]["kind"];
  sourceActor: number;
  sourceId?: string;
  grantedNight: number;
  armedOnNight: number | null;
}

// 两个原 WeakMap 随实际 owner 整体迁移；计数只在成功安装后推进，不查询 RNG 或时钟。
const owners = new WeakMap<DeathGunReadView, GunOwner>(),
  counters = new WeakMap<World, number>();

export function allDeathGuns(role: RoleComponent | undefined): DeathGunReadView[] {
  return Object.values(
    ((role as { readonly privateState: { readonly deathAbilities?: unknown } } | undefined)
      ?.privateState.deathAbilities ?? {}) as Readonly<Record<string, DeathGunReadView>>,
  ).sort((a, b) => a.id.localeCompare(b.id));
}

export function findDeathGun(
  role: RoleComponent | undefined,
  id: string,
): DeathGunReadView | undefined {
  return allDeathGuns(role).find((gun) => gun.id === id);
}

function bind(world: World, actorId: number, gun: DeathGun): void {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  if (!role || role.camp !== Camp.Good || !life?.alive || version === undefined)
    throw new Error("death_ability_owner_invalid");
  owners.set(gun, {
    world,
    actorId,
    role,
    roleKind: role.role,
    camp: role.camp,
    privateState: role.privateState,
    life,
    version,
    id: gun.id,
    source: gun.source,
    sourceKind: gun.source.kind,
    sourceActor: gun.source.actorId,
    ...(gun.source.kind === "transfer" ? { sourceId: gun.source.abilityId } : {}),
    grantedNight: gun.grantedNight,
    armedOnNight: gun.armedOnNight,
  });
}

export function deathGunOwnerCurrent(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  onDeath = false,
): boolean {
  const owner = owners.get(gun);
  if (!owner || owner.world !== world || owner.actorId !== actorId) return false;
  const version = aliveLifeVersion(owner.life);
  return (
    gun.id === owner.id &&
    gun.kind === "gun" &&
    gun.source === owner.source &&
    gun.source.kind === owner.sourceKind &&
    gun.source.actorId === owner.sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === owner.sourceId) &&
    gun.sourceDisclosed === false &&
    gun.grantedNight === owner.grantedNight &&
    gun.armedOnNight === owner.armedOnNight &&
    world.getComponent(actorId, COMPONENT.Role) === owner.role &&
    owner.role.role === owner.roleKind &&
    owner.role.camp === owner.camp &&
    owner.role.privateState === owner.privateState &&
    findDeathGun(owner.role, gun.id) === gun &&
    world.getComponent(actorId, COMPONENT.Alive) === owner.life &&
    (onDeath
      ? !owner.life.alive && version === owner.version + 1
      : owner.life.alive && version === owner.version)
  );
}

function emit(
  events: GameEvent[],
  actorId: number,
  gun: Pick<
    DeathGunReadView,
    "id" | "grantedNight" | "armedOnNight" | "remaining" | "disabled" | "deathExpired"
  >,
  operation: "granted" | "armed" | "disabled" | "enabled" | "transferred_out",
  abilityId = gun.id,
): void {
  events.push({
    timestamp: Date.now(),
    type: "death_ability_changed",
    payload: {
      actorId,
      abilityId,
      operation,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
      remaining: gun.remaining,
      disabled: gun.disabled,
      deathExpired: gun.deathExpired,
    },
  });
}

/** 安装原体证明后写入目标库存，再推进计数并发表授予事实；发布失败保留此前写入，不回滚安装。 */
export function grantDeathGun(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  night: number,
  events: GameEvent[],
): DeathGunReadView {
  const from = world.getComponent(fromId, COMPONENT.Role),
    to = world.getComponent(toId, COMPONENT.Role);
  if (
    fromId === toId ||
    !from ||
    from.camp !== Camp.Good ||
    !world.getComponent(fromId, COMPONENT.Alive)?.alive ||
    !to ||
    to.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    !Number.isSafeInteger(night) ||
    night < 1
  )
    throw new Error("death_ability_grant_invalid");
  if (allDeathGuns(to).length) throw new Error("death_ability_gun_already_owned");
  const next = (counters.get(world) ?? 0) + 1,
    id = `gift-gun:${next}`;
  if (
    (
      (to.privateState as { readonly retiredDeathAbilityIds?: unknown }).retiredDeathAbilityIds as
        string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_id_retired");
  const gun: DeathGun = {
    id,
    kind: "gun",
    source: { kind: "gift", actorId: fromId },
    sourceDisclosed: false,
    grantedNight: night,
    armedOnNight: null,
    remaining: 1,
    disabled: false,
    deathExpired: false,
  };
  bind(world, toId, gun);
  const stored = ((
    to.privateState as { deathAbilities?: Record<string, DeathGun> }
  ).deathAbilities ??= {}) as Record<string, DeathGun>;
  stored[id] = gun;
  counters.set(world, next);
  emit(events, toId, gun, "granted");
  return gun;
}

// 武装先核原 owner 与库存，随后依次写枪的 armedOnNight、证明中的同值，最后发布事实。
export function armDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  night: number,
  events: GameEvent[],
): void {
  if (!Number.isSafeInteger(night) || night < gun.grantedNight)
    throw new Error("death_ability_activation_invalid");
  if (
    !deathGunOwnerCurrent(world, actorId, gun) ||
    gun.armedOnNight !== null ||
    gun.disabled ||
    gun.deathExpired ||
    gun.remaining === 0
  )
    return;
  (gun as { armedOnNight: number | null }).armedOnNight = night;
  owners.get(gun)!.armedOnNight = night;
  emit(events, actorId, gun, "armed");
}

export function activeDeathGun(
  world: World,
  actorId: number,
  id: string,
  day: number,
  onDeath = false,
): DeathGunReadView | undefined {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  return gun &&
    deathGunOwnerCurrent(world, actorId, gun, onDeath) &&
    gun.armedOnNight !== null &&
    gun.armedOnNight <= day &&
    gun.remaining === 1 &&
    !gun.disabled &&
    !gun.deathExpired
    ? gun
    : undefined;
}

/** 捕获的是原枪／来源字段并延迟核资格，不创建行动许可；剩弹、武装与当前性仍在实际查询时复核。 */
export function captureDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  day: number,
  current: () => boolean,
) {
  const id = gun.id,
    kind = gun.kind,
    source = gun.source,
    sourceKind = source.kind,
    sourceActor = source.actorId,
    sourceId = source.kind === "transfer" ? source.abilityId : undefined;
  const disclosed = gun.sourceDisclosed,
    granted = gun.grantedNight,
    armed = gun.armedOnNight;
  const disabled = gun.disabled,
    expired = gun.deathExpired;
  const isCurrent = () =>
    current() &&
    gun.id === id &&
    gun.kind === kind &&
    gun.source === source &&
    gun.source.kind === sourceKind &&
    gun.source.actorId === sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === sourceId) &&
    gun.sourceDisclosed === disclosed &&
    gun.grantedNight === granted &&
    gun.armedOnNight === armed &&
    gun.disabled === disabled &&
    gun.deathExpired === expired &&
    deathGunOwnerCurrent(world, actorId, gun, true);
  return {
    isCurrent,
    isEligible: () => isCurrent() && activeDeathGun(world, actorId, id, day, true) === gun,
  };
}

// 死亡回调前捕获原枪及发布字段；首次死亡的 version+1 保持枪权，不能提前永久到期。
export function firstDeathGuns(
  world: World,
  actorId: number,
): Array<{
  actorId: number;
  gun: DeathGunReadView;
  id: string;
  grantedNight: number;
  armedOnNight: number | null;
}> {
  return allDeathGuns(world.getComponent(actorId, COMPONENT.Role))
    .filter((gun) => !gun.deathExpired && deathGunOwnerCurrent(world, actorId, gun, true))
    .map((gun) => ({
      actorId,
      gun,
      id: gun.id,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
    }));
}

// 外层收尾逐枪依次清剩弹、禁用、标永久到期；事实只用先前捕获字段，失败不回滚已写前缀。
export function finishDeathGuns(
  rows: ReturnType<typeof firstDeathGuns>,
  events: GameEvent[],
): void {
  for (const { actorId, gun, id, grantedNight, armedOnNight } of rows) {
    if (gun.deathExpired) continue;
    (gun as { remaining: 0 | 1 }).remaining = 0;
    (gun as { disabled: boolean }).disabled = true;
    (gun as { deathExpired: boolean }).deathExpired = true;
    emit(
      events,
      actorId,
      { id, grantedNight, armedOnNight, remaining: 0, disabled: true, deathExpired: true },
      "disabled",
      id,
    );
  }
}

export function setDeathGunEnabled(
  world: World,
  actorId: number,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  if (!gun || !deathGunOwnerCurrent(world, actorId, gun))
    throw new Error("death_ability_instance_unavailable");
  if (enabled && gun.deathExpired) throw new Error("death_ability_expired");
  if (gun.disabled === !enabled) return;
  (gun as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, gun, enabled ? "enabled" : "disabled");
}

// 先建立接收者新证明／库存，再删源实例、登记退休 ID，最后源转出→目标授予；不直接搬旧对象。
export function transferDeathGun(
  world: World,
  fromId: number,
  toId: number,
  id: string,
  events: GameEvent[],
): DeathGunReadView {
  const source = world.getComponent(fromId, COMPONENT.Role),
    target = world.getComponent(toId, COMPONENT.Role),
    gun = findDeathGun(source, id);
  if (
    !gun ||
    fromId === toId ||
    !deathGunOwnerCurrent(world, fromId, gun) ||
    !target ||
    target.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    allDeathGuns(target).length ||
    (
      (target.privateState as { readonly retiredDeathAbilityIds?: unknown })
        .retiredDeathAbilityIds as string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_transfer_invalid");
  const received: DeathGun = {
    ...projectDeathGun(gun),
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  };
  delete (received as DeathGun & { status?: string }).status;
  bind(world, toId, received);
  (
    ((target.privateState as { deathAbilities?: Record<string, DeathGun> }).deathAbilities ??=
      {}) as Record<string, DeathGun>
  )[id] = received;
  delete (
    (source!.privateState as { readonly deathAbilities?: unknown }).deathAbilities as Record<
      string,
      DeathGun
    >
  )[id];
  (
    ((source!.privateState as { retiredDeathAbilityIds?: string[] }).retiredDeathAbilityIds ??=
      []) as string[]
  ).push(id);
  emit(events, fromId, gun, "transferred_out");
  emit(events, toId, received, "granted");
  return received;
}

// 枪目标、生命与行动许可由调用者复核；这里只将原枪剩弹写为 0，不新增授权、复检或事实。
export function consumeDeathGunShot(gun: DeathGunReadView): void {
  (gun as { remaining: 0 | 1 }).remaining = 0;
}

/**
 * 负责从原 World 与明确阶段构造引擎行动请求。输入为演员、窗口、允许工具和中立摘要；
 * 输出固定日次、阶段、约束及玩家可见事实，完整构造之后交规则集按原顺序接线机制绑定。
 * 具体机制仍唯一持有权限、期限别名与资源提交；请求数据副本不是行动许可。
 * 本工厂不渲染本地化文案、不序列化运行范围，也不据阶段字符串新增角色权限。
 */
import { bindRulesetActionRequest } from "../../rulesets/action-request-bindings";
import type { MessageRef } from "@ai-werewolf-arena/game-contract";
import type { ActionRequest, ActionRequestExtras } from "@ai-werewolf-arena/game-contract/requests";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type {
  ActionStage,
  ActionWindow,
  EntityId,
  Phase,
  ToolName,
} from "@ai-werewolf-arena/game-contract";
import { World } from "../../core/domain/world";
import { buildAgentVisibleEventFeed } from "./agent_visible_event_feed";
import { buildTurnConstraintContext } from "./turn_constraints_context";

/**
 * 统一创建游戏对 Agent 的行动请求。
 *
 * 该工厂统一填入原生请求的日次、细粒度 stage、玩家可见事件与结构化行动约束；
 * 调用方提供机制附加数据，运行时权限仍由具体机制保存，不混入这些公共字段。
 */
export class GameActionRequestFactory {
  constructor(
    private readonly world: World,
    private readonly events: readonly GameEvent[],
    private readonly day: number,
  ) {}

  create(input: {
    phase: Phase;
    actorId: EntityId;
    allowedTools: ToolName[];
    stage: ActionStage;
    requiresAction: boolean;
    summary: string | MessageRef;
    actionWindow?: ActionWindow;
    context?: ActionRequestExtras;
  }): ActionRequest {
    // 公共事实由工厂生成；调用方只能提供机制特有的信息。
    const request: ActionRequest = {
      phase: input.phase,
      actorId: input.actorId,
      allowedTools: [...input.allowedTools],
      ...(input.actionWindow ? { actionWindow: input.actionWindow } : {}),
      context: {
        ...structuredClone(input.context ?? {}),
        day: this.day,
        stage: input.stage,
        turn_constraints: buildTurnConstraintContext({
          requiresAction: input.requiresAction,
          allowedTools: input.allowedTools,
          summary: input.summary,
        }),
        visible_events: buildAgentVisibleEventFeed(this.world, [...this.events], input.actorId),
      },
    };
    // 原输入的阶段仍逐分支读取，不用已构造的 context.stage 替代后续 getter；World 也只在命中时读。
    bindRulesetActionRequest(request, {
      stage: () => input.stage,
      world: () => this.world,
    });
    return request;
  }
}

/**
 * Owns Magician night exchange bindings and target-remapping receipts. Inputs are original
 * player bodies and the paired choice; outputs preserve current mappings, cancellation and
 * close/abort behavior. It never lets a stale source redirect a later native action using the
 * old exchange.
 */
import type { MagicianReadState } from "@ai-werewolf-arena/game-contract";
import { isWolfSorcererBoard, resolveWolfSorcererNightTarget } from "../wolf_sorcerer/night_frame";
import { matchingExchangePairs } from "../trickster/exile_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getMagicianState, projectMagicianState, MAGICIAN_ROLE } from "./state";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: MagicianReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function stateIdentity(role: RoleComponent): string {
  const view = projectMagicianState(role);
  if (!view) throw new Error("magician_original_state_revoked");
  return JSON.stringify(view);
}
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("magician_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("magician_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getMagicianState(actor.role) !== b.state || stateIdentity(actor.role) !== b.expectedState)
    throw new Error("magician_original_state_revoked");
  return b;
}
export function installMagicianBoard(world: World): void {
  if (boards.has(world)) throw new Error("magician_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: MagicianReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("magician_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("magician_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("magician_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("magician_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === MAGICIAN_ROLE) {
      if (actorId !== null) throw new Error("magician_original_roster_invalid");
      actorId = id;
      state = getMagicianState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("magician_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: stateIdentity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isMagicianBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function beginMagicianNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("magician_night_invalid");
  const used = new Set<number>();
  for (const choice of projectMagicianState(b.players.get(b.actorId)!.role)!.history)
    if (choice.pair) {
      used.add(choice.pair[0]);
      used.add(choice.pair[1]);
    }
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible =
    day >= b.state.firstNight && b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = { day, closed: false, committed: !eligible, pair: null, targets };
  return eligible ? b.actorId : null;
}
export function magicianChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitMagicianExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("magician_choice_scope_invalid");
  let chosen: [number, number] | null = null;
  if (pair !== null) {
    if (types.isProxy(pair) || !Array.isArray(pair))
      throw new Error("magician_choice_target_invalid");
    const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      pair as object,
    );
    const a = descriptors["0"]?.value,
      z = descriptors["1"]?.value;
    if (
      Reflect.ownKeys(descriptors).length !== 3 ||
      descriptors.length?.value !== 2 ||
      !Number.isSafeInteger(a) ||
      !Number.isSafeInteger(z) ||
      a <= 0 ||
      z <= 0
    )
      throw new Error("magician_choice_target_invalid");
    if (a === z || !n.targets.get(a)?.life.alive || !n.targets.get(z)?.life.alive)
      throw new Error("magician_choice_target_invalid");
    chosen = a < z ? [a, z] : [z, a];
  }
  Object.defineProperty(b.state.history, String(b.state.history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
  b.expectedState = stateIdentity(b.players.get(actorId)!.role);
  n.pair = chosen && Object.freeze([chosen[0], chosen[1]] as [number, number]);
  n.committed = true;
}
export interface MagicianResolvedTarget {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function resolveMagicianNightTarget(
  world: World,
  day: number,
  requestedId: number,
  kind: "night_action" | "death_shot" = "night_action",
): MagicianResolvedTarget {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  const original = b.players.get(requestedId);
  if (!original || !original.life.alive) throw new Error("magician_target_invalid");
  const originalShot = kind === "death_shot" && b.state.deathShotTargetPolicy === "original";
  // A second swap exchanges occupants of positions; resolve W(raw) before M.
  // Intermediate occupants may already be dead in a night death-shot chain.
  const second = isWolfSorcererBoard(world)
    ? resolveWolfSorcererNightTarget(
        world,
        day,
        requestedId,
        originalShot ? "original" : "intermediate",
      )
    : null;
  const intermediateId = second?.effectiveId ?? requestedId;
  const pair = originalShot ? null : n.pair;
  const effectiveId = pair
    ? intermediateId === pair[0]
      ? pair[1]
      : intermediateId === pair[1]
        ? pair[0]
        : intermediateId
    : intermediateId;
  const effective = b.players.get(effectiveId)!;
  if (kind === "night_action" && !effective.life.alive) throw new Error("magician_target_invalid");
  const nightPair = n.pair;
  const requestedVersion = aliveLifeVersion(original.life)!;
  const scope: NightLifeScope = Object.freeze({
    id: effectiveId,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  return Object.freeze({
    requestedId,
    effectiveId,
    scope,
    isCurrent: () => {
      try {
        return (
          requireBoard(world) === b &&
          b.night === n &&
          n.pair === nightPair &&
          (!second || second.isCurrent()) &&
          !n.closed &&
          originalPlayer(world, original) &&
          originalPlayer(world, effective) &&
          original.life.alive &&
          aliveLifeVersion(original.life) === requestedVersion &&
          aliveLifeVersion(effective.life) === scope.version
        );
      } catch {
        return false;
      }
    },
  });
}
